body.content:
你在前面几节课中接触过两种操作页面的方式：
**方式一：命令式（Imperative）—— 直接告诉 {{term:DOM}} "做什么"**

```js
// 添加一项：创建元素、设置内容、挂载到页面
let card = document.createElement("div");
card.textContent = "肖邦夜曲";
listEl.appendChild(card);
// 删除一项：找到元素、调用 remove()
document.querySelector("#card-3").remove();
// 修改一项：找到元素、修改内容
document.querySelector("#card-2 h3").textContent = "新曲名";
```

每一步都要精确操作 {{term:DOM}}。简单直接，但程序复杂时很容易混乱——你需要同时记住"数据在哪"和"{{term:DOM}} 在哪"。
**方式二：声明式（Declarative）—— 告诉程序 "我想要什么"，然后调用{{term:渲染}}{{term:函数}}**

```js
let pieces = [{ name: "肖邦夜曲" }, { name: "布兰登堡" }];
function render(list) {
  // 清空容器
  listEl.innerHTML = "";
  // 根据数据重新生成全部 DOM
  list.forEach(function(p) {
    let card = document.createElement("div");
    card.textContent = p.name;
    listEl.appendChild(card);
  });
}
render(pieces);  // 初始渲染
// 需要添加时：只修改数据，然后重新渲染
pieces.push({ name: "月光奏鸣曲" });
render(pieces);
// 删除、修改——全部一样：先改数据，再 render()
```

这就是**数据驱动**——数据是"唯一的真相来源"，页面只是数据的反映。

starter.css:
h1 {
  text-align: center;
  color: #8B2E2E;
}
#pieceList {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: 400px;
  margin: 16px auto;
  min-height: 60px;
}
.piece-item {
  background: #FFFAF2;
  border: 1px solid #D4C5A9;
  border-radius: 8px;
  padding: 12px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #8B2E2E;
  font-weight: 500;
}
.piece-item button {
  background: transparent;
  color: #C94545;
  border: 1px solid #D4C5A9;
  border-radius: 6px;
  padding: 4px 12px;
  cursor: pointer;
  font-size: 13px;
}
.piece-item button:hover {
  background: #C94545;
  color: white;
}
.toolbar {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-top: 16px;
  align-items: center;
}
#nameInput {
  padding: 8px 12px;
  border: 1px solid #D4C5A9;
  border-radius: 6px;
  font-size: 14px;
  width: 180px;
  color: #3D2B1F;
  background: #FFFAF2;
}
.toolbar button {
  padding: 8px 16px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 14px;
}
#addBtn {
  background: #8B2E2E;
  color: white;
}
#addBtn:hover {
  background: #C94545;
}
#clearBtn {
  background: #6B5A4E;
  color: white;
}
.stats {
  text-align: center;
  color: #6B5A4E;
  margin-top: 12px;
  font-size: 14px;
}

starter.js:
// 当前是命令式——直接操作 DOM。你的任务：改成数据驱动模式
let listEl = document.querySelector("#pieceList");
let nameInput = document.querySelector("#nameInput");
let countEl = document.querySelector("#count");
// 添加曲目（命令式——直接创建元素）
document.querySelector("#addBtn").addEventListener("click", function() {
  let name = nameInput.value.trim();
  if (!name) return;
  let item = document.createElement("div");
  item.classList.add("piece-item");
  item.innerHTML = name + ' <button class="del-btn">✕</button>';
  // 给删除按钮绑定事件
  item.querySelector(".del-btn").addEventListener("click", function() {
    item.remove();
    updateCount();
  });
  listEl.appendChild(item);
  nameInput.value = "";
  updateCount();
});
// 清空全部
document.querySelector("#clearBtn").addEventListener("click", function() {
  listEl.innerHTML = "";
  updateCount();
});
function updateCount() {
  countEl.textContent = "共 " + listEl.children.length + " 首曲目";
}
updateCount();
